def gen(rng):
    vals = [0, 2**32 - 1, 32, 2**15, 2**20, 2**15 + 2**20, 2**5 + 2**15 + 2**20, 1, 2**31, 2**32 - 33, 1048576 + 32768]
    for b5 in (0, 1):
        for b15 in (0, 1):
            for b20 in (0, 1):
                vals.append((b5 << 5) | (b15 << 15) | (b20 << 20))
    for _ in range(10):
        vals.append(rng.randrange(2**32))
    seen = []
    for v in vals:
        if v not in seen:
            seen.append(v)
    return [str(v) for v in seen]

